import{NextRequest,NextResponse}from"next/server";import{getServerContext}from"@/lib/context";import{writeAudit}from"@/lib/audit";
export async function GET(request:NextRequest,{params}:{params:Promise<{id:string}>}){const{id}=await params;const{supabase,societyId,wingId,userId}=await getServerContext();const{data:doc,error}=await supabase.from("vendor_documents").select("id,vendor_id,title,file_name,storage_path,status").eq("id",id).eq("society_id",societyId).single();if(error||!doc?.storage_path)return NextResponse.json({error:"Document not found or access denied."},{status:404});const download=request.nextUrl.searchParams.get("download")==="1";const{data,error:signedError}=await supabase.storage.from("society-documents").createSignedUrl(doc.storage_path,60,download?{download:doc.file_name??"vendor-document"}:undefined);if(signedError||!data?.signedUrl)return NextResponse.json({error:"Secure document link could not be created."},{status:500});await writeAudit({societyId,wingId,actorUserId:userId,action:"DOCUMENT_ACCESSED",entityType:"vendor_document",entityId:doc.id,metadata:{vendorId:doc.vendor_id,accessType:download?"DOWNLOAD":"PREVIEW",status:doc.status}});return NextResponse.redirect(data.signedUrl);}
